-- Seed af referencedata. Genereret fra belastning/data/*.json – ret JSON-filerne og kør scripts-generer-data.mjs.

on conflict (navn) do update set salgsareal=excluded.salgsareal, lagerareal=excluded.lagerareal, ovrigtareal=excluded.ovrigtareal, kasser=excluded.kasser, sco=excluded.sco, tilvalg=excluded.tilvalg;


on conflict (id) do update set navn=excluded.navn, kw=excluded.kw, df=excluded.df, cosphi=excluded.cosphi, kilde=excluded.kilde, opdateret=now();
